wait(S) {              // P operation
    while (S <= 0)
        ;              // busy wait
    S--;
}
signal(S) {            // V operation
    S++;
}

// mutual exclusion with a binary semaphore mutex = 1
do {
    wait(mutex);
    /* critical section */
    signal(mutex);
    /* remainder section */
} while (true);
